const DB_NAME='yoyu-history-v2';let dbPromise;let backupScope='yoyu-ledger-data-v1';
export function setBackupScope(scope){backupScope=scope;folder=null;disconnectDrive()}
export const getBackupScope=()=>backupScope;
function db(){if(!globalThis.indexedDB)return Promise.reject(Error('此瀏覽器不支援歷史備份儲存'));if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,1);r.onupgradeneeded=()=>{for(const name of ['versions','handles'])if(!r.result.objectStoreNames.contains(name))r.result.createObjectStore(name,{keyPath:'id'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});return dbPromise}
async function storeOp(name,mode,action){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction(name,mode),request=action(tx.objectStore(name));let out;request.onsuccess=()=>{out=request.result};request.onerror=()=>reject(request.error);tx.oncomplete=()=>resolve(out);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('備份被中止'))})}
export async function saveVersion(state,label='自動快照',scope=backupScope){const versions=await history(scope);const text=JSON.stringify(state);if(versions[0]?.text===text)return versions[0];const row={scope,id:scope+':'+Date.now()+'-'+crypto.getRandomValues(new Uint32Array(1))[0],time:Date.now(),label,count:state.transactions.length,text};await storeOp('versions','readwrite',s=>s.put(row));const rows=[row,...versions];for(const old of rows.slice(30))await storeOp('versions','readwrite',s=>s.delete(old.id));return row}
export async function history(scope=backupScope){return (await storeOp('versions','readonly',s=>s.getAll())).filter(r=>(r.scope||'yoyu-ledger-data-v1')===scope).sort((a,b)=>b.time-a.time)}
function bytesTo64(bytes){let s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(s)}
function from64(s){if(typeof s!=='string'||s.length>50000000)throw Error('加密備份格式錯誤');return Uint8Array.from(atob(s),c=>c.charCodeAt(0))}
async function derive(password,salt,usage){if(!crypto.subtle)throw Error('加密功能需要 HTTPS 安全連線');if(password.length<8)throw Error('備份密碼至少8個字元');const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,[usage])}
export async function encryptBackup(state,password){const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await derive(password,salt,'encrypt');const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(JSON.stringify(state)));return {format:'yoyu-encrypted-v1',kdf:'PBKDF2-SHA256',iterations:250000,salt:bytesTo64(salt),iv:bytesTo64(iv),data:bytesTo64(new Uint8Array(cipher))}}
export async function decryptBackup(envelope,password){if(envelope?.format!=='yoyu-encrypted-v1'||envelope.iterations!==250000)throw Error('不是支援的加密備份');try{const salt=from64(envelope.salt),iv=from64(envelope.iv);if(salt.length!==16||iv.length!==12)throw Error('格式');const key=await derive(password,salt,'decrypt'),plain=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,from64(envelope.data));return JSON.parse(new TextDecoder().decode(plain))}catch{throw Error('密碼不正確或備份檔已損毀')}}
let folder=null;export async function chooseFolder(){if(!window.showDirectoryPicker)throw Error('此瀏覽器不支援選擇備份資料夾；可使用加密下載或 Google Drive');folder=await window.showDirectoryPicker({id:'yoyu-backups',mode:'readwrite'});await storeOp('handles','readwrite',s=>s.put({id:'backup-folder:'+backupScope,handle:folder}));return folder.name}
export async function folderInfo(){if(!folder)folder=(await storeOp('handles','readonly',s=>s.get('backup-folder:'+backupScope)))?.handle||null;return folder?{name:folder.name,permission:await folder.queryPermission({mode:'readwrite'})}:null}
export async function authorizeFolder(){const info=await folderInfo();if(!info)throw Error('請先選擇資料夾');const p=await folder.requestPermission({mode:'readwrite'});if(p!=='granted')throw Error('尚未允許寫入資料夾');return folder.name}
export async function writeFolderBackup(envelope){const info=await folderInfo();if(info?.permission!=='granted')throw Error('備份資料夾尚未授權，請重新連接');const name='日常有餘_'+new Date().toISOString().replace(/[:.]/g,'-')+'.yoyu.json';const handle=await folder.getFileHandle(name,{create:true});const writer=await handle.createWritable();await writer.write(JSON.stringify(envelope));await writer.close();return name}
const SCOPE='https://www.googleapis.com/auth/drive.file';let token='',expires=0,clientId='',scriptPromise,folderId='';
export function driveStatus(){return {connected:!!token&&Date.now()<expires,expires,configured:!!clientId}}
async function loadGIS(){if(globalThis.google?.accounts?.oauth2)return;if(!scriptPromise)scriptPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.onload=resolve;script.onerror=()=>{scriptPromise=null;reject(Error('無法載入 Google 登入元件'))};document.head.append(script)});await scriptPromise}
export async function prepareDrive(id){if(!/^[a-zA-Z0-9._-]+\.apps\.googleusercontent\.com$/.test(id))throw Error('請先設定有效的 Google OAuth Web Client ID');clientId=id;await loadGIS()}
export function connectDrive(){if(!clientId||!globalThis.google?.accounts?.oauth2)throw Error('請先儲存 OAuth Client ID 並載入登入元件');return new Promise((resolve,reject)=>{const c=google.accounts.oauth2.initTokenClient({client_id:clientId,scope:SCOPE,include_granted_scopes:false,callback:r=>{if(r.error||!r.access_token){reject(Error('Google 未授權備份存取'));return}token=r.access_token;expires=Date.now()+(Number(r.expires_in)||3600)*1000-60000;folderId='';resolve(driveStatus())},error_callback:()=>reject(Error('Google 授權視窗未完成，請確認允許彈出視窗'))});c.requestAccessToken({prompt:'consent'})})}
export function disconnectDrive(){token='';expires=0;folderId=''}
async function drive(url,opts={}){if(!driveStatus().connected)throw Error('Google 授權已過期，請重新連接；帳目仍保存在本機');const r=await fetch(url,{...opts,headers:{Authorization:'Bearer '+token,...opts.headers},signal:AbortSignal.timeout(30000)});if(r.status===401){disconnectDrive();throw Error('Google 授權已過期，請重新連接')}if(!r.ok)throw Error('Google Drive 操作未完成（'+r.status+'），未標記為已備份');return r}
async function backupFolder(){if(folderId)return folderId;const q="mimeType='application/vnd.google-apps.folder' and trashed=false and appProperties has { key='yoyuKind' and value='backups' }";const data=await (await drive('https://www.googleapis.com/drive/v3/files?q='+encodeURIComponent(q)+'&fields=files(id,name)&pageSize=100')).json();if(data.files?.length){folderId=data.files[0].id;return folderId}const created=await (await drive('https://www.googleapis.com/drive/v3/files',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:'日常有餘加密備份',mimeType:'application/vnd.google-apps.folder',appProperties:{yoyuKind:'backups'}})})).json();folderId=created.id;return folderId}
export async function uploadDriveBackup(envelope){const parent=await backupFolder(),name='日常有餘_'+new Date().toISOString().replace(/[:.]/g,'-')+'.yoyu.json',boundary='yoyu-'+crypto.getRandomValues(new Uint32Array(2)).join('');const meta={name,parents:[parent],mimeType:'application/json',appProperties:{yoyuKind:'encrypted-backup'}};const body='--'+boundary+'\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n'+JSON.stringify(meta)+'\r\n--'+boundary+'\r\nContent-Type: application/json\r\n\r\n'+JSON.stringify(envelope)+'\r\n--'+boundary+'--';const data=await (await drive('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,name,createdTime',{method:'POST',headers:{'Content-Type':'multipart/related; boundary='+boundary},body})).json();if(!data.id)throw Error('Google 未回傳備份編號');return data}
export async function listDriveBackups(){const q="trashed=false and appProperties has { key='yoyuKind' and value='encrypted-backup' }";const data=await (await drive('https://www.googleapis.com/drive/v3/files?q='+encodeURIComponent(q)+'&fields=files(id,name,createdTime),nextPageToken&orderBy=createdTime%20desc&pageSize=30')).json();return data.files||[]}
export async function readDriveBackup(id){if(!/^[\w-]+$/.test(id))throw Error('備份編號不正確');const meta=await (await drive('https://www.googleapis.com/drive/v3/files/'+id+'?fields=id,appProperties,size')).json();if(meta.appProperties?.yoyuKind!=='encrypted-backup'||Number(meta.size)>25000000)throw Error('這不是此工具建立的有效備份');return (await drive('https://www.googleapis.com/drive/v3/files/'+id+'?alt=media')).json()}
